-- GATD Solutions seed — imports the former hardcoded lib/solutionsData.js + lib/programsData.js
-- into parent_solutions / child_solutions / solution_programs.
-- Re-runnable: upserts each parent, replaces the listed children (cascades their programs).
-- Run AFTER solutions_schema.sql, against the CMS database (phpMyAdmin → Import).
SET NAMES utf8mb4;
START TRANSACTION;

INSERT INTO parent_solutions (slug, title, is_active, sort_order) VALUES ('certified-programs', 'Certified Programs', 1, 0)
  ON DUPLICATE KEY UPDATE title=VALUES(title), is_active=1, delete_status=0;

DELETE FROM child_solutions WHERE slug IN ('strategic-hr', 'change-management', 'ppp', 'kpis');

INSERT INTO child_solutions (parent_solution_id, slug, eyebrow, title, description, subheading, subtext, banner, card_image, programmes_heading, map_image, gains_heading, gains, why_heading, why_badge, why_image, audience_badge, audience_heading, audience_image, audience, brochure, rating, reviews, is_active, sort_order)
VALUES ((SELECT id FROM parent_solutions WHERE slug='certified-programs' LIMIT 1), 'strategic-hr', 'Certified Programs', 'Strategic Human Resources, Business Leadership and Management', 'This suite offers eight executive-level certifications that help specialists become strategic leaders. You will learn how to improve performance, leadership, and human capital to achieve real business results. All programs are accredited by EIU-Paris.', 'Advance Your Expertise in Strategic HR and Management with Global ATD', 'The Strategic Human Resources, Business Leadership and Management Certifications Program helps professionals connect people, performance, and business strategy for greater impact. Its specialised courses build advanced skills in leadership, talent development, and HR effectiveness. The program prepares HR leaders to drive growth and add real value.', '/images/solutions/strategic-hr/banner.jpg', '/images/solutions/Certified-Programs/certified-1.jpg', 'Strategic HR Programme Suite', '/images/solutions/strategic-hr/map.jpg', 'What You\'ll Gain From This Certification Suite', '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","text":"Develop deep expertise in all key areas of human resources and management across modern business environments"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","text":"Earn EIU-Paris and GATD accreditation, recognized worldwide, and connect with top-tier professional network"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","text":"Learn practical frameworks & strategies to help you turn your team\'s talent into real business growth you can measure"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","text":"Build the leadership skills you need to succeed confidently in the modern executive boardroom environment"},{"id":5,"iconSrc":"/images/solutions/strategic-hr/5.svg","text":"Apply advanced tools to help your team work more efficiently and deliver consistently high-performance results"}]', 'Why this Suite is Worth the Investment', 'Invest in building results that last', '/images/solutions/strategic-hr/plan.jpg', 'Who is This', 'Programme Suite Designed For?', '/images/solutions/strategic-hr/programme-suits.jpg', '["Senior HR Leaders & Directors","Aspiring C-Suite & High-Potentials","Business Unit Heads & GMs","L&D Specialists","Executive Consultants & Advisors"]', '/brochures/strategic-human-resources-and-management.pdf', NULL, 0, 1, 0);

INSERT INTO child_solutions (parent_solution_id, slug, eyebrow, title, description, subheading, subtext, banner, card_image, programmes_heading, map_image, gains_heading, gains, why_heading, why_badge, why_image, audience_badge, audience_heading, audience_image, audience, brochure, rating, reviews, is_active, sort_order)
VALUES ((SELECT id FROM parent_solutions WHERE slug='certified-programs' LIMIT 1), 'change-management', 'Certified Programs', 'Change Management', 'This certification equips practitioners with the methodologies, tools, and leadership skills to plan, implement, and sustain organisational change effectively.', 'Lead Change with Confidence and Competence', 'GATD\'s Change Management certification programme is grounded in globally recognised frameworks, preparing you to guide people and organisations through complex transitions.', '/images/solutions/strategic-hr/banner.jpg', '/images/solutions/Certified-Programs/certified-2.jpg', NULL, '/images/solutions/strategic-hr/map.jpg', 'What You\'ll Gain From This Certification', '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","text":"Master globally recognised change management frameworks and methodologies"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","text":"Earn a globally recognised change management certification from EIU-Paris and GATD"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","text":"Build the leadership skills to guide organisations through complex, large-scale transitions"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","text":"Develop effective change communication and stakeholder engagement strategies"},{"id":5,"iconSrc":"/images/solutions/strategic-hr/5.svg","text":"Apply practical tools that accelerate adoption and sustain change outcomes"},{"id":6,"iconSrc":"/images/solutions/strategic-hr/6.svg","text":"Build change resilience and agility into your organisation\'s culture and leadership practice"}]', 'Why This Certification is Worth the Investment', 'Invest in building results that last', '/images/solutions/strategic-hr/plan.jpg', 'Who is This', 'Certification Designed For?', '/images/solutions/strategic-hr/programme-suits.jpg', '["Change Management Practitioners","HR & OD Leaders","Project & Programme Managers","Senior Managers & Directors","Business Transformation Leads"]', NULL, NULL, 0, 1, 1);

INSERT INTO child_solutions (parent_solution_id, slug, eyebrow, title, description, subheading, subtext, banner, card_image, programmes_heading, map_image, gains_heading, gains, why_heading, why_badge, why_image, audience_badge, audience_heading, audience_image, audience, brochure, rating, reviews, is_active, sort_order)
VALUES ((SELECT id FROM parent_solutions WHERE slug='certified-programs' LIMIT 1), 'ppp', 'Certified Programs', 'Public Private Partnerships', 'This programme builds the expertise required to structure, negotiate, and manage successful PPP arrangements — bridging public sector goals with private sector capabilities.', 'Master the Complexity of Public Private Partnerships', 'Participants gain practical knowledge of PPP frameworks, financial structuring, risk allocation, and stakeholder management to deliver sustainable infrastructure and services.', '/images/solutions/strategic-hr/banner.jpg', '/images/solutions/Certified-Programs/certified-3.jpg', NULL, '/images/solutions/strategic-hr/map.jpg', 'What You\'ll Gain From This Certification', '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","text":"Master the legal, financial, and governance frameworks that underpin successful PPP structures"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","text":"Earn a globally recognised PPP certification that opens doors to international projects"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","text":"Develop skills in PPP risk allocation, negotiation, and contract management"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","text":"Build stakeholder management capabilities that align public and private sector interests"},{"id":5,"iconSrc":"/images/solutions/strategic-hr/5.svg","text":"Apply practical PPP financial modelling and project structuring techniques"},{"id":6,"iconSrc":"/images/solutions/strategic-hr/6.svg","text":"Deliver sustainable infrastructure and services through well-structured PPP arrangements"}]', 'Why This Certification is Worth the Investment', 'Invest in building results that last', '/images/solutions/strategic-hr/plan.jpg', 'Who is This', 'Certification Designed For?', '/images/solutions/strategic-hr/programme-suits.jpg', '["Government Officials & Policy Makers","Infrastructure & Project Finance Leaders","Legal & Procurement Professionals","Private Sector Partnership Managers","Development Finance Executives"]', NULL, NULL, 0, 1, 2);

INSERT INTO child_solutions (parent_solution_id, slug, eyebrow, title, description, subheading, subtext, banner, card_image, programmes_heading, map_image, gains_heading, gains, why_heading, why_badge, why_image, audience_badge, audience_heading, audience_image, audience, brochure, rating, reviews, is_active, sort_order)
VALUES ((SELECT id FROM parent_solutions WHERE slug='certified-programs' LIMIT 1), 'kpis', 'Certified Programs', 'Key Performance Indicators (KPIs)', 'Learn to design, implement, and manage KPI systems that drive organisational accountability and align daily activity with strategic objectives.', 'Build a Performance Culture with Meaningful KPIs', 'This certification covers KPI design principles, data collection, dashboarding, and the leadership behaviours that turn metrics into sustained performance improvements.', '/images/solutions/strategic-hr/banner.jpg', '/images/solutions/Certified-Programs/certified-4.jpg', NULL, '/images/solutions/strategic-hr/map.jpg', 'What You\'ll Gain From This Certification', '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","text":"Design meaningful KPI systems that connect individual performance to organisational strategy"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","text":"Earn a globally recognised KPI certification from EIU-Paris and GATD"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","text":"Build performance dashboards that enable data-driven leadership decisions at every level"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","text":"Develop a high-accountability performance culture through transparent metric systems"},{"id":5,"iconSrc":"/images/solutions/strategic-hr/5.svg","text":"Implement KPI governance frameworks that ensure consistency, accuracy, and relevance"},{"id":6,"iconSrc":"/images/solutions/strategic-hr/6.svg","text":"Transform raw data into actionable insights that drive sustained performance improvement"}]', 'Why This Certification is Worth the Investment', 'Invest in building results that last', '/images/solutions/strategic-hr/plan.jpg', 'Who is This', 'Certification Designed For?', '/images/solutions/strategic-hr/programme-suits.jpg', '["Strategy & Planning Leaders","Performance Management Professionals","HR & Organisational Development Teams","Finance & Operations Managers","Business Unit Leaders"]', NULL, NULL, 0, 1, 3);

INSERT INTO solution_programs (child_solution_id, slug, eyebrow, title, description, banner, card_image, subheading, subtext, rating, reviews, price_cents, currency, pricing_period, pricing_heading, pricing_description, brochure, registration_heading, overview, gains_heading, gains, focus_heading, focus_areas, faqs, facilitator, certification, layout_type, layout_data, is_published, is_active, sort_order)
VALUES ((SELECT id FROM child_solutions WHERE slug='strategic-hr' LIMIT 1), 'strategic-hr-business-partnership', 'Certified Programs', 'Strategic HR Business Partnership & Beyond (SHRBP) Certification', 'A 3-day executive SHRBP certification programme to empower senior HR leaders to become strategic boardroom advisors confidently.', '/images/solutions/Programs/strategic-hr-banner.jpg', '/images/solutions/strategic-hr/prog-1.jpg', NULL, NULL, 4.9, 486, 385000, 'SGD', '/Person', 'Why It\'s Worth', 'By enrolling, you\'ll earn a respected EIU-Paris credential and learn practical frameworks to help you grow from an HR practitioner into a Strategic Business Partner. You\'ll develop the business skills to connect people strategy with company goals, turning human capital into a real driver of growth and success.', '/brochures/strategic-hr-business-partnership.pdf', 'Strategic HR Business Partnership & Beyond (SHRBP)', '{"title":"Strategic HR Business Partner Certification","description":"This program is a strategic initiative designed to equip you with the financial acumen, consulting frameworks, and organisational models needed to sit at the table with the CEO and CFO as an equal, reinforcing your vital role in leadership discussions.","image":"/images/solutions/strategic-hr/SHRBP-overview.png"}', NULL, '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/6.svg","text":"Position HR as a strategic business partner"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/5.svg","text":"Align people strategy with business goals"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/4.svg","text":"Influence leaders using data-driven insights"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/3.svg","text":"Build and execute effective workforce strategies"},{"id":5,"iconSrc":"/images/solutions/strategic-hr/2.svg","text":"Demonstrate measurable business impact"},{"id":6,"iconSrc":"/images/solutions/strategic-hr/1.svg","text":"Strengthen collaboration to drive talent performance."}]', 'Focuses on Developing', '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","title":"Strategic HR Alignment","description":"Strategic thinking aligned with business priorities"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","title":"Data-Driven Decision Making","description":"Data-driven HR decision-making for measurable outcomes"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","title":"Influential Leadership & Stakeholders","description":"Leadership influence and effective stakeholder management"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","title":"Performance-Focused Workforce Strategy","description":"Workforce strategies are directly linked to organisational performance"}]', '[{"id":1,"question":"Who is this programme for?","answer":"This program is for Senior HR Managers, Heads of HR, and Directors who lead organisational strategy."},{"id":2,"question":"Is this certification recognised?","answer":"“The program is accredited by the European International University (EIU-Paris), adding value to your professional profile.”"},{"id":3,"question":"Can I claim this under my corporate training budget?","answer":"Yes, most of our participants are sponsored by their organisations."},{"id":4,"question":"How long is the programme?","answer":"The programme runs over 3 intensive days, designed to be completed without disrupting your working schedule."},{"id":5,"question":"I have a different question. Who should I contact?","answer":"Please contact us via email at ceo@globalatd.com for assistance."}]', '{"name":"Prof. Dr. Joel Farnworth","role":"Dean of Business and Management Studies, EIU-Paris","image":"/images/solutions/strategic-hr/Dr_Joel.png","bg":"/images/solutions/strategic-hr/program_facilitator_BG.png","expertise":["Human Resource Management","Leadership Development","Managerial Skills Development","Corporate Strategy Creation and Implementation","Performance Management","Strategic HRM"],"biography":["Coach and Consultant","Strategic HR Management","Impactive Leadership","Creating and Implementing Corporate Strategy","Senior Management Advisor"]}', '{"badge":"Recognised Speaker Credentials","heading":"Certification\\non Successful\\nCompletion","image":"/images/solutions/strategic-hr/certificate_image.jpg","paragraphs":["When you complete the program, you will receive the Strategic HR Business Partner Certification from EIU Paris and the Global Association for Training & Development (GATD).","This certification recognizes your expertise in boardroom-level HR strategy. It shows your commitment to global standards, innovative leadership, and your ability to drive business success through strategic HR management."]}', 'strategic_pillars', '{"heading":"3 Strategic Pillars","badge":"3 Days","days":[{"label":"DAY 1","id":"day1"},{"label":"DAY 2","id":"day2"},{"label":"DAY 3","id":"day3"}],"modulesByDay":{"day1":[{"id":1,"arrowTitle":"Establishing & Delivering Strategic HR","labelPosition":"bottom","sideLabel":"HR Role Evolution","sideDescription":"Exploring the evolving role of HR Business Partnership and strategic HR services"},{"id":2,"arrowTitle":"Next Generation HR","labelPosition":"top","sideLabel":"Future HR Models","sideDescription":"Discussing administrator, BP, and predictive contributor roles, and creating people strategy"},{"id":3,"arrowTitle":"The HRBP Role","labelPosition":"bottom","sideLabel":"HRBP Capabilities","sideDescription":"Defining the HRBP role as a generalist and one-stop solution center, emphasizing influence and change facilitation"},{"id":4,"arrowTitle":"Business Strategies to Performance Deliverables","labelPosition":"top","sideLabel":"Performance Alignment","sideDescription":"Linking business strategy to performance deliverables, KPIs, and commitment"}],"day2":[{"id":1,"arrowTitle":"Talent Management & Succession","labelPosition":"bottom","sideLabel":"Organisational Readiness","sideDescription":"Identifying HIPOs, planning the workforce, and securing succession for critical roles ensures a strong talent pipeline"},{"id":2,"arrowTitle":"People Management","labelPosition":"top","sideLabel":"Leadership Excellence","sideDescription":"Effective leadership combines impactful style, practical L & M examples, clear success indicators, and precise selection criteria"},{"id":3,"arrowTitle":"Reward Offerings & Management","labelPosition":"bottom","sideLabel":"Compensation Strategy","sideDescription":"Balancing fixed and variable cash options, trending benefits, brand differentiation, and market positioning drives competitive advantage"},{"id":4,"arrowTitle":"HR Technology and Data","labelPosition":"top","sideLabel":"HR Analytics","sideDescription":"Leveraging current and future tech, HR tools, data dashboards, and metrics aligns workforce insights with business impact"}],"day3":[{"id":1,"arrowTitle":"Organisation Development & Change","labelPosition":"bottom","sideLabel":"Organisational Design","sideDescription":"Core OD elements—diversity, engagement, values, and the work experience—drive a truly engaged organisation"},{"id":2,"arrowTitle":"Current People Challenges & Solutions?","labelPosition":"top","sideLabel":"People Strategy","sideDescription":"Addressing current challenges by focusing on top priorities, implementing targeted solutions, and taking clear first steps"},{"id":3,"arrowTitle":"Predictive People Analytics","labelPosition":"bottom","sideLabel":"Future Insights","sideDescription":"Key predictions from AI, consultants, participants, and the trainer highlight emerging trends and future directions"},{"id":4,"arrowTitle":"Human Capital Trends","labelPosition":"top","sideLabel":"Next Normal","sideDescription":"Anticipating likely needs and responses, focusing on flexible work, CSR, engagement, and inclusive HR advice for the upcoming strategic plan"}]}}', 1, 1, 0);

INSERT INTO solution_programs (child_solution_id, slug, eyebrow, title, description, banner, card_image, subheading, subtext, rating, reviews, price_cents, currency, pricing_period, pricing_heading, pricing_description, brochure, registration_heading, overview, gains_heading, gains, focus_heading, focus_areas, faqs, facilitator, certification, layout_type, layout_data, is_published, is_active, sort_order)
VALUES ((SELECT id FROM child_solutions WHERE slug='strategic-hr' LIMIT 1), 'business-people-leadership', 'Certified Programs', 'Impactful Business and People Leadership', 'Master the psychology of high-performance teams and the business acumen of the C-Suite. This 3-day immersive experience empowers leaders to unlock their full potential and achieve impactful results.', '/images/solutions/strategic-hr/impactful-business-and-people-leadership-banner.png', '/images/solutions/strategic-hr/prog-2.jpg', 'Lead People. Drive Business. Create Impact.', 'This certification blends leadership theory with practical application — equipping participants to lead with clarity, empathy, and strategic purpose.', 4.8, 342, 385000, 'SGD', '/Person', 'Why It\'s Worth', 'This investment gives you an EIU-Paris credential and a clear plan to reduce leadership challenges and help your team work faster. It turns your people from a cost into a key driver of profit, delivering fast and noticeable results for your organisation.', '/brochures/impactive-business-and-people-leadership.pdf', 'Impactful Business and People Leadership', '{"title":"Impactful Business and People Leadership","description":"This program helps you build leadership skills that link business results with people management. You’ll see how your actions affect decisions, team motivation, and company success. You’ll also get practical tips for leading clearly, encouraging accountability, and achieving strong results.","image":"/images/solutions/strategic-hr/impactful-business-overview.png"}', NULL, '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","text":"Business and people leader-ship skills to lead with impact and drive performance."},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","text":"Master the non-verbal & verbal cues that command respect in the boardroom"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","text":"Learn the science of building teams that are self-regulating and high-output"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","text":"Learn to translate people’s goals into the Profit and Loss (P&L) language"},{"id":5,"iconSrc":"/images/solutions/strategic-hr/5.svg","text":"Develop the mental flexibility to lead through uncertainty and rapid growth"},{"id":6,"iconSrc":"/images/solutions/strategic-hr/6.svg","text":"Build influence and alignment across senior stakeholders and teams."}]', 'Focuses on Developing', '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","title":"Executive Presence","description":"Learn how to use both body language and words to earn respect in meetings and on the job."},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","title":"High-Trust Culture","description":"Discover how to build teams that manage themselves well and deliver strong results."},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","title":"Adaptive Leadership","description":"Build the flexibility you need to lead through change, restructuring, and fast growth."},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","title":"Commercial Vision","description":"Find out how to connect your team’s goals to the financial results your CEO and Board want to see"}]', '[{"id":1,"question":"How does this leadership program differ from standard management training?","answer":"Most courses teach you how to manage tasks. This program is different—it helps you build strategic influence. We combine insights from psychology and business to help you make a bigger impact in your organisation."},{"id":2,"question":"Is this certification suitable for leaders outside of the HR function?","answer":"Yes. Although GATD hosts the program, it’s made for any Senior Manager, Director, or VP who leads people and drives results. The focus is on leadership skills for everyone, not just HR."},{"id":3,"question":"How will this improve my Executive Presence?","answer":"You’ll learn the words and body language that help you earn respect in meetings. We’ll also give you tools to persuade others and get support for your ideas, even if you don’t have direct authority."}]', '{"name":"Prof. Dr. Joel Farnworth","role":"Dean of Business and Management Studies, EIU-Paris","image":"/images/solutions/strategic-hr/Dr_Joel.png","bg":"/images/solutions/strategic-hr/program_facilitator_BG.png","expertise":["Human Resource Management","Leadership Development","Managerial Skills Development","Corporate Strategy Creation and Implementation","Performance Management","Strategic HRM"],"biography":["Coach and Consultant","Strategic HR Management","Impactive Leadership","Creating and Implementing Corporate Strategy","Senior Management Advisor"]}', '{"badge":"Recognised Speaker Credentials","heading":"Certification\\non Successful\\nCompletion","image":"/images/solutions/strategic-hr/certificate_image.jpg","paragraphs":["Upon successful completion of the programme, participants will be awarded the Impactful Business and People Leadership Certification, jointly issued by European International University (EIU-Paris) and the Global Association of Training & Development (GATD). This credential affirms your leadership excellence and opens doors across international markets.","This certification validates your leadership standing across international markets."]}', 'learning_journey', '{"heading":"The 3-Day Learning Journey","badge":"3 Days","days":[{"label":"DAY 1","pillars":[{"title":"Leadership Execution","description":"Aligns leadership vision and people skills with managerial planning and control to turn strategy into measurable results","footer":"The People Balance"},{"title":"Managerial Maturity","description":"Defines management capabilities across levels, showing how responsibilities and skills evolve as leaders grow within an organization","footer":"Managers are Important"},{"title":"Decision Clarity","description":"Clarifies stay-or-exit decisions, concentrates on the vital few priorities, and recognizes peripherals rising in strategic importance","footer":"The demands of the LED"},{"title":"Workplace Excellence","description":"Drives talent attraction and engagement through key initiatives while monitoring results for continuous improvement","footer":"Employers of the Choice"}]},{"label":"DAY 2","pillars":[{"title":"Survey Insights","description":"Analyzes survey data to inform actionable steps that enhance performance and engagement","footer":"The Engaged Leader & Manager"},{"title":"Strategy Blueprint","description":"Builds clear strategic intent using frameworks like BCG, Porter, and PESTEL, translating them into actionable plans, KPIs, and deliverables","footer":"The Strategic Leader"},{"title":"Channel Strategy","description":"Identifies optimal internal and external channels while focusing on key factors driving progress","footer":"The Talent Challenge"},{"title":"Case Insights","description":"Examines leadership approaches, strategic moves, rebranding efforts, and crisis responses across notable companies","footer":"Learning from the Negative"}]},{"label":"DAY 3","pillars":[{"title":"Leadership Examples","description":"Showcases diverse leadership styles and philosophies from iconic global figures and organizations","footer":"Learning from the Positive"},{"title":"Stakeholder Roles","description":"Highlights the involvement and impact of AI, consultants, participants, and trainers in driving initiatives","footer":"Predictive Analytics Future L & M Challengers"},{"title":"Insight Sources","description":"Aggregates information from surveys, platforms like Glassdoor, and analysts or media to provide comprehensive overview","footer":"A Data Driven World"},{"title":"Success Factors","description":"Highlights essential success elements, reviews business and people strategies, and provides actionable implementation takeaways","footer":"Final thoughts"}]}]}', 1, 1, 1);

INSERT INTO solution_programs (child_solution_id, slug, eyebrow, title, description, banner, card_image, subheading, subtext, rating, reviews, price_cents, currency, pricing_period, pricing_heading, pricing_description, brochure, registration_heading, overview, gains_heading, gains, focus_heading, focus_areas, faqs, facilitator, certification, layout_type, layout_data, is_published, is_active, sort_order)
VALUES ((SELECT id FROM child_solutions WHERE slug='strategic-hr' LIMIT 1), 'performance-rewards', 'Certified Programs', 'Performance Development and Rewards Management', 'A 2-day Executive Certification to move beyond annual appraisals and basic payroll into high-impact performance architecture and total rewards strategy.', '/images/solutions/strategic-hr/performance-development-and-rewards-management-banner.png', '/images/solutions/strategic-hr/prog-3.jpg', 'Build a Performance Culture That Rewards What Matters', 'From performance appraisal design to total rewards strategy, participants gain the tools to create systems that are fair, transparent, and aligned with organisational values.', 4.8, 278, 280000, 'SGD', '/Person', 'Why It\'s Worth', 'This investment gives you a respected EIU-Paris credential and practical tools to improve your reward systems. It helps you connect individual performance to company results, making compensation a real driver of productivity instead of just a fixed cost.', '/brochures/performance-development-and-reward-management.pdf', 'Performance Development and Reward Management', '{"title":"Performance Development and Rewards Management","description":"This program shows how performance management and reward systems affect motivation, engagement, and business results. You will learn practical ways to improve performance, give feedback, and design rewards that match your company’s goals. The course helps you move beyond traditional appraisals and create systems that connect individual efforts to company success.","image":"/images/solutions/strategic-hr/performance_development-overview.jpg"}', NULL, '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/6.svg","text":"Design effective performance development frameworks"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/5.svg","text":"Align performance management with organisational goals"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/4.svg","text":"Apply structured feedback and appraisal processes"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/3.svg","text":"Build fair and motivating reward and performance management systems"},{"id":5,"iconSrc":"/images/solutions/strategic-hr/2.svg","text":"Strengthen employee engagement and retention"},{"id":6,"iconSrc":"/images/solutions/strategic-hr/1.svg","text":"Developed a learning transfer action plan to enhance performance, reward practices"}]', 'Focuses on Developing', '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","title":"Performance Architecture","description":"Designing agile frameworks that replace outdated appraisals with continuous, high-output feedback loops."},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","title":"Total Rewards Strategy","description":" Engineering a competitive Reward and Performance Management system that balances financial and non-financial incentives."},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","title":"Strategic KPI Engineering","description":"Aligning individual performance targets directly with organisational P&L and long-term business goals."},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","title":"Behavioural Incentive Design","description":"Utilising behavioural science to motivate top-tier performance without inflating fixed labour costs."}]', '[{"id":1,"question":"Who should enroll in this certification?","answer":"This programme is perfect for HR professionals, HR business partners, and managers who make decisions about performance and rewards."},{"id":2,"question":"Is the programme practical or theoretical?","answer":"The programme is practical and focuses on real-world use, not just theory."},{"id":3,"question":"Will I receive a globally recognised certification?","answer":"Yes, you will receive a certification from both EIU Paris and GATD upon completion of the programme."}]', '{"name":"Prof. Dr. Joel Farnworth","role":"Dean of Business and Management Studies, EIU-Paris","image":"/images/solutions/strategic-hr/Dr_Joel.png","bg":"/images/solutions/strategic-hr/program_facilitator_BG.png","expertise":["Human Resource Management","Leadership Development","Managerial Skills Development","Corporate Strategy Creation and Implementation","Performance Management","Strategic HRM"],"biography":["Coach and Consultant","Strategic HR Management","Impactive Leadership","Creating and Implementing Corporate Strategy","Senior Management Advisor"]}', '{"badge":"Recognised Speaker Credentials","heading":"Certification\\non Successful\\nCompletion","image":"/images/solutions/strategic-hr/certificate_image.jpg","paragraphs":["When you complete the programme, you’ll receive the Performance Development and Rewards Management Certification, issued by EIU Paris and the Global Association of Training & Development (GATD).","This certification shows you can manage performance development and reward practices that support your organisation’s performance and employee engagement."]}', 'hexagons', '{"heading":"2 Days of Performance Engineering","badge":"2 Days","days":[{"label":"DAY 1","sessions":[{"color":"dark","title":"Execution Alignment","description":"End-to-end performance management that links strategy to delivery by addressing challenges and strengthening performance connections"},{"color":"red","title":"Growth Enablement","description":"Development management aligned with talent management to build an inclusive, opportunity-rich culture that strengthens employer-of-choice appeal"}]},{"label":"DAY 2","sessions":[{"color":"dark","title":"Reward Strategy","description":"Market-aligned rewards using differentiated POT principles, supported by targeted initiatives to drive fairness, motivation, and performance"},{"color":"red","title":"People Impact","description":"Measures how engagement and implementation influence employer-of-choice strength, stay-or-go decisions, and key personal and organisational takeaways"}]}]}', 1, 1, 2);

INSERT INTO solution_programs (child_solution_id, slug, eyebrow, title, description, banner, card_image, subheading, subtext, rating, reviews, price_cents, currency, pricing_period, pricing_heading, pricing_description, brochure, registration_heading, overview, gains_heading, gains, focus_heading, focus_areas, faqs, facilitator, certification, layout_type, layout_data, is_published, is_active, sort_order)
VALUES ((SELECT id FROM child_solutions WHERE slug='strategic-hr' LIMIT 1), 'resourcing-talent-learning', 'Certified Programs', 'Resourcing, Talent and Learning Management', 'A 2-day Executive Certification for HR Leaders ready to move beyond “hiring and training” to building a sustainable, high-velocity talent ecosystem.', '/images/solutions/strategic-hr/resourcing-talent-and-learning-management-banner.png', '/images/solutions/strategic-hr/prog-4.jpg', 'Attract, Develop and Retain the Talent That Drives Growth', 'Participants develop strategic resourcing frameworks, talent pipeline methodologies, and learning design capabilities that deliver measurable organisational impact.', 4.7, 214, 280000, 'SGD', '/Person', 'Why It\'s Worth', 'Acquire a globally recognised credential. With this investment, you acquire a respected EIU-Paris credential and learn how to move from costly, last-minute hiring to a more proactive, sustainable approach. It helps you close skill gaps and link workforce development directly to your company’s growth. ', '/brochures/resourcing-talent-and-learning-management.pdf', 'Resourcing Talent and Learning Management', '{"title":"Resourcing Talent and Learning Management Certification","description":"Move from reactive recruitment to strategic workforce modelling. This 2-day program equips you with frameworks to attract elite talent, build a self-sustaining leadership pipeline, and prove the financial ROI of Learning & Development.","image":"/images/solutions/strategic-hr/resourcing_talent_overview.png"}', NULL, '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/6.svg","text":"Manage resourcing and recruitment in a structured and strategic way"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/5.svg","text":"Identify and develop talent to meet current and future business needs"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/4.svg","text":"Design learning initiatives that support performance and growth"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/3.svg","text":"Build integrated talent and learning strategies aligned with organisational goals"},{"id":5,"iconSrc":"/images/solutions/strategic-hr/2.svg","text":"Strengthen HR’s contribution to long-term business success."},{"id":6,"iconSrc":"/images/solutions/strategic-hr/1.svg","text":"Enhanced ability to implement integrated talent and learning strategies"}]', 'Focuses on Developing', '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","title":"Predictive Resourcing","description":"Move beyond vacancies to strategic workforce modelling that anticipates future skill gaps."},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","title":"The Talent Ecosystem","description":"Design internal mobility and retention frameworks that keep your highest-value assets from leaving."},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","title":"High Impact Learning ROI","description":"Transition from hours of training to performance improvement that is measurable in dollars."},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","title":"Succession Architecture","description":"Secure the organisation\'s future by building a robust, data-backed leadership pipeline."}]', '[{"id":1,"question":"Is this program focused on the administrative side of recruitment?","answer":"No, this program is about high-level strategy. Instead of just filling positions, it teaches Human Capital Engineering. You’ll learn to design workforce models and talent systems that support your company’s long-term financial goals."},{"id":2,"question":"Can I really measure the financial ROI of Learning and Development?","answer":"Yes, you can. The program includes Learning ROI Calibration as a key part. We give you clear formulas and tools to turn training results into financial numbers that your Board and CFO will value."},{"id":3,"question":"What is the global standing of the EIU-Paris certification?","answer":"The European International University (EIU-Paris) is a leading professional school. Earning this certification shows the global market that you have top-level skills in talent systems and can lead at an international standard."}]', '{"name":"Prof. Dr. Joel Farnworth","role":"Dean of Business and Management Studies, EIU-Paris","image":"/images/solutions/strategic-hr/Dr_Joel.png","bg":"/images/solutions/strategic-hr/program_facilitator_BG.png","expertise":["Human Resource Management","Leadership Development","Managerial Skills Development","Corporate Strategy Creation and Implementation","Performance Management","Strategic HRM"],"biography":["Coach and Consultant","Strategic HR Management","Impactive Leadership","Creating and Implementing Corporate Strategy","Senior Management Advisor"]}', '{"badge":"Recognised Speaker Credentials","heading":"Certification\\non Successful\\nCompletion","image":"/images/solutions/strategic-hr/certificate_image.jpg","paragraphs":["Upon successful completion of the programme, participants will be awarded the Resourcing, Talent and Learning Management Certification, jointly issued by EIU Paris and the Global Association of Training & Development (GATD).","This certification validates your capability to manage resourcing, talent, and learning initiatives that support organisational performance and workforce sustainability."]}', 'curriculum', '{"heading":"The 2-Day Executive Curriculum","badge":"2 Days","days":[{"label":"DAY 1","sessions":[{"color":"red","title":"Resourcing","bullets":["Resourcing channels","Recruitment funnel","Technology advancements","CB interviewing"]},{"color":"dark","title":"HiPo Talent","bullets":["Finding high-potential talent","9-box tool","Assessment/development centres","Talent development progress and succession"]}]},{"label":"DAY 2","sessions":[{"color":"red","title":"Learning Management","bullets":["For performance enhancement","For development enhancement","Specific for HiPos","Initiatives to improve"]},{"color":"dark","title":"Metrics","bullets":["External – Glassdoor","Internal – engagement surveys","Tracking, reporting and initiatives","Takeaways – learning transfer"]}]}]}', 1, 1, 3);

INSERT INTO solution_programs (child_solution_id, slug, eyebrow, title, description, banner, card_image, subheading, subtext, rating, reviews, price_cents, currency, pricing_period, pricing_heading, pricing_description, brochure, registration_heading, overview, gains_heading, gains, focus_heading, focus_areas, faqs, facilitator, certification, layout_type, layout_data, is_published, is_active, sort_order)
VALUES ((SELECT id FROM child_solutions WHERE slug='strategic-hr' LIMIT 1), 'impactive-hr', 'Certified Programs', 'Impactive HR for the Uninitiated', 'This 2-day executive masterclass helps non-HR leaders understand people strategy, reduce human capital risks, and improve organisational performance', '/images/solutions/strategic-hr/impactive-hr-for-the-uninitiated-banner.png', '/images/solutions/strategic-hr/impactive-hr-for-the-uninitiated.jpg', 'Build a Strong HR Foundation from Day One', 'This programme equips newcomers to HR with the essential knowledge, tools, and frameworks needed to contribute meaningfully and grow into confident HR practitioners.', 4.7, 168, 280000, 'SGD', '/Person', 'Why It\'s Worth', 'This investment provides a globally recognised EIU-Paris credential and the HR literacy needed to mitigate human capital risks and protect your budget. It shifts people leadership from a functional burden to a strategic tool for engineering a high-performing team that drives measurable P&L growth.', '/brochures/impactive-hr-for-the-uninitiated.pdf', 'Impactive HR for the Uninitiated', '{"title":"Impactive HR for the Unitiated","description":"This certification helps you connect business operations with people strategy. The programme builds essential HR knowledge and skills that are useful in today’s workplace. You will learn key HR practices such as workforce planning, hiring, supporting performance, and using HR systems.","image":"/images/solutions/strategic-hr/impactive-hr-overview.jpg"}', NULL, '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","text":"Gain a clear understanding of core HR concepts and essential functions"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","text":"Assist in basic HR processes and important workforce initiatives to drive results"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","text":"Actively participate in talent acquisition and development initiatives and efforts"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","text":"Get tools to turn people-related challenges into business results and returns"},{"id":5,"iconSrc":"/images/solutions/strategic-hr/5.svg","text":"Communicate effectively and confidently with HR teams and stakeholders"},{"id":6,"iconSrc":"/images/solutions/strategic-hr/6.svg","text":"Gain practical HR skills to align people strategies with business operations"}]', 'Focuses on Developing', '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","title":"Commercial HR Literacy","description":"Learn how to turn complex HR ideas into practical steps for business growth and efficiency"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","title":"Tactical Talent Acquisition","description":"Gain skills to hire and select the right people so every new team member adds value"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","title":"Legal & Compliance Shielding","description":"Learn the basics of labour laws and workforce rules to reduce risks for you and your organisation"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","title":"Culture & Alignment Management","description":"Align your team’s actions with your company’s goals to help your business strategy succeed"}]', '[{"id":1,"question":"Do I need prior HR experience to attend?","answer":"No, you do not need any HR experience. This program is made for beginners. We avoid jargon and focus on practical, strategic HR skills every business leader should know."},{"id":2,"question":"Who should enrol in this certification?","answer":"This programme is perfect for new HR professionals, people changing careers, and business professionals who support HR work."},{"id":3,"question":"Is this programme practical?","answer":"Yes, the programme uses real workplace examples and teaches how to apply HR basics"}]', '{"name":"Prof. Dr. Joel Farnworth","role":"Dean of Business and Management Studies, EIU-Paris","image":"/images/solutions/strategic-hr/Dr_Joel.png","bg":"/images/solutions/strategic-hr/program_facilitator_BG.png","expertise":["Human Resource Management","Leadership Development","Managerial Skills Development","Corporate Strategy Creation and Implementation","Performance Management","Strategic HRM"],"biography":["Coach and Consultant","Strategic HR Management","Impactive Leadership","Creating and Implementing Corporate Strategy","Senior Management Advisor"]}', '{"badge":"Recognised Speaker Credentials","heading":"Certification\\non Successful\\nCompletion","image":"/images/solutions/strategic-hr/certificate_image.jpg","paragraphs":["Upon successful completion, participants will receive the Impactive HR for the Uninitiated Certification, jointly issued by EIU Paris and the Global Association of Training & Development (GATD).","This recognition celebrates strong cross-functional leadership and a commitment to excellent people management, creative talent strategies, and raising business standards through effective human capital practices."]}', 'people_strategy_panels', '{"heading":"2 Days of People Strategy Mastery","badge":"2 Days","days":[{"label":"DAY 1","sessions":[{"title":"Strategic Partnership","bullets":["HR administration to business partner","Capabilities & structures","Strategic advice and counsel the people aspects","Balancing business & people impact"]},{"title":"People Strategy","bullets":["Business strategy delivery","Performance & development management","Rewards management","Talent management"]}]},{"label":"DAY 2","sessions":[{"title":"People Excellence","bullets":["Organisational development","Employer of choice — the stay/go equation","HR metrics and business impact","Initiatives for improvement"]},{"title":"Data Insights","bullets":["The power of data","Internal (engagement)","External (Glassdoor)","Takeaways – learning transfer"]}]}]}', 1, 1, 4);

INSERT INTO solution_programs (child_solution_id, slug, eyebrow, title, description, banner, card_image, subheading, subtext, rating, reviews, price_cents, currency, pricing_period, pricing_heading, pricing_description, brochure, registration_heading, overview, gains_heading, gains, focus_heading, focus_areas, faqs, facilitator, certification, layout_type, layout_data, is_published, is_active, sort_order)
VALUES ((SELECT id FROM child_solutions WHERE slug='strategic-hr' LIMIT 1), 'progressing-org-development', 'Certified Programs', 'Progressing Organization Development', 'This 2-day executive certification teaches you how to align your company’s structure with its goals. You’ll gain hands-on skills in organisational transformation and building a strong company culture.', '/images/solutions/strategic-hr/progressing-organization-development-banner.png', '/images/solutions/strategic-hr/progressing-organizational-development.jpg', 'Build the Capability to Transform Organisations From Within', 'This programme equips practitioners with the OD frameworks, diagnostic tools, and change leadership skills needed to design organisations that are built to perform, adapt, and thrive.', 4.8, 196, 280000, 'SGD', '/Person', 'Why It\'s Worth', 'This investment gives you an EIU-Paris credential and the tools to spot and fix problems in your organisation, making it more flexible. It helps you build a strong company culture that breaks down barriers and supports long-term growth.', '/brochures/progressing-organization-development.pdf', 'Progressing Organisation Development', '{"title":"Progressing Organisation Development Certification","description":"The program helps you build skills in organizational assessment, change management, and improving company culture. You will use proven models to find issues, design solutions, and support lasting performance improvements. The focus is on practical tools so you can lead development that brings people, processes, and goals together.","image":"/images/solutions/strategic-hr/progressing_organization_overview.jpg"}', NULL, '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","text":"You’ll be able to use the language of ‘Systems Thinking’ leaders in the C-Suite expect"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","text":"Assess your organization’s strengths and identify areas for development"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","text":"Design and put into action effective changes and development plans"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","text":"Build a stronger company culture, boost engagement, and improve performance"},{"id":5,"iconSrc":"/images/solutions/strategic-hr/5.svg","text":"Lead strategic organizational development projects with confidence"},{"id":6,"iconSrc":"/images/solutions/strategic-hr/6.svg","text":"Built practical skills to improve organisational processes and enhance team growth"}]', 'Focuses on Developing', '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","title":"Organisational Diagnosis","description":"Use data-driven methods to spot problems and performance slowdowns in your company."},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","title":"Architecture & Design","description":"Engineering organisational structures that eliminate silos and accelerate decision-making."},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","title":"Cultural Engineering","description":"Turn company culture into a measurable asset that helps employees work toward shared goals."},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","title":"Transformation Management","description":"Lead complex changes in your organization while keeping productivity high."}]', '[{"id":1,"question":"How is this different from a Change Management course?","answer":"Change management usually reacts to specific projects. This organizational development certification takes a proactive approach, focusing on the whole system so your organization can keep adapting and stay healthy."},{"id":2,"question":"What will I learn from this programme?","answer":"You’ll learn how to assess your organization’s needs, lead change, and design development plans."},{"id":3,"question":"Can I apply this to a small company?","answer":"Yes. Whether you’re growing a startup or improving a large company, the same principles of organizational health and design apply."}]', '{"name":"Prof. Dr. Joel Farnworth","role":"Dean of Business and Management Studies, EIU-Paris","image":"/images/solutions/strategic-hr/Dr_Joel.png","bg":"/images/solutions/strategic-hr/program_facilitator_BG.png","expertise":["Human Resource Management","Leadership Development","Managerial Skills Development","Corporate Strategy Creation and Implementation","Performance Management","Strategic HRM"],"biography":["Coach and Consultant","Strategic HR Management","Impactive Leadership","Creating and Implementing Corporate Strategy","Senior Management Advisor"]}', '{"badge":"Recognised Speaker Credentials","heading":"Certification\\non Successful\\nCompletion","image":"/images/solutions/strategic-hr/certificate_image.jpg","paragraphs":["When you finish the program, you’ll receive the Progressing Organization Development Certification, awarded by EIU Paris and the Global Association of Training & Development (GATD).","This certification shows you have the skills to lead development projects that improve performance, engagement, and company culture."]}', 'org_framework', '{"heading":"2 Days of Organizational Mastery","badge":"2 Days","days":[{"label":"DAY 1","sessions":[{"color":"red","title":"Values","bullets":["Strategic intentions – the what?","The values context – the how?","Specific values for your firm","Embedding and enhancement"]},{"color":"dark","title":"Diversity","bullets":["Original diversity emphasis","Emergence of gender diversity","The data – impact on success","Diversity initiatives – on merit"]}]},{"label":"DAY 2","sessions":[{"color":"red","title":"Engagement","bullets":["Gaining willing commitment","Engagement impact on results","Engagement surveys","Improvement initiatives"]},{"color":"dark","title":"OD Metrics","bullets":["Track and improve","OD & business results – connections","Internal/external data","Takeaways – learning transfer"]}]}]}', 1, 1, 5);

INSERT INTO solution_programs (child_solution_id, slug, eyebrow, title, description, banner, card_image, subheading, subtext, rating, reviews, price_cents, currency, pricing_period, pricing_heading, pricing_description, brochure, registration_heading, overview, gains_heading, gains, focus_heading, focus_areas, faqs, facilitator, certification, layout_type, layout_data, is_published, is_active, sort_order)
VALUES ((SELECT id FROM child_solutions WHERE slug='strategic-hr' LIMIT 1), 'advancing-trainer-development', 'Certified Programs', 'Advancing Trainer Development (ToT)', 'This 2-day executive certification helps you move past basic training delivery and focus on building high-impact learning programs and performance consulting.', '/images/solutions/strategic-hr/advancing-trainer-development-banner.png', '/images/solutions/strategic-hr/advancing-trainer-development-ToT.jpg', 'Develop World-Class Trainers Who Inspire and Deliver Results', 'This programme transforms subject-matter experts into skilled facilitators — equipping them to design engaging learning experiences, manage diverse audiences, and measure the impact of their training.', 4.8, 231, 280000, 'SGD', '/Person', 'Why It\'s Worth', 'With this investment, you earn a respected EIU-Paris certification and learn how to move from just delivering content to making a real impact as a performance consultant. You’ll be able to design training that drives real change and clear results.', '/brochures/advancing-trainer-development.pdf', 'Advancing Trainer Development', '{"title":"Advancing Trainer Development","description":"Boost your organisation’s L&D results with the Advancing Trainer Development certification. This program covers practical and advanced skills, including facilitation, learner engagement, training design, and evaluation. You will learn how to create, deliver, and evaluate training programs that meet both learner and business needs.","image":"/images/solutions/strategic-hr/advancing_trainer_development_overview.jpg"}', NULL, '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","text":"Design effective, highly engaging and learner-centric training programmes"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","text":"Facilitate meaningful learning sessions with confidence, clarity, and engagement"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","text":"Learn modern instructional design techniques tailored for high-impact programs"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","text":"Use proven methods to calculate ROI of training and present results to your CFO"},{"id":5,"iconSrc":"/images/solutions/strategic-hr/5.svg","text":"Stronger executive presence and communication skills for leading senior-level sessions"},{"id":6,"iconSrc":"/images/solutions/strategic-hr/6.svg","text":"Create and deliver training that drives engagement, skill development, and results"}]', 'Focuses on Developing', '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","title":"Learning Architecture Design","description":"Build effective curricula that address business challenges and close performance gaps"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","title":"Performance Consulting","description":"Learn frameworks to advise senior leaders on developing talent and measuring ROI"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","title":"Knowledge Transfer Optimisation","description":"Use cognitive science to help learners remember and apply knowledge in important situations"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","title":"Impact Evaluation (ROI)","description":"Apply data-driven methods to measure the financial and operational results of training"}]', '[{"id":1,"question":"Is this a basic Train the Trainer course?","answer":"No, this is an advanced certification for experienced professionals. It focuses on learning strategy and how to design and measure training that drives business results."},{"id":2,"question":"What will I learn from this programme?","answer":"You will learn to design, deliver, and evaluate training programs that improve learning results."},{"id":3,"question":"Is the EIU-Paris certification recognised globally?","answer":"Yes, it is a respected professional credential that proves your expertise in strategic L&D at a global level."}]', '{"name":"Prof. Dr. Joel Farnworth","role":"Dean of Business and Management Studies, EIU-Paris","image":"/images/solutions/strategic-hr/Dr_Joel.png","bg":"/images/solutions/strategic-hr/program_facilitator_BG.png","expertise":["Human Resource Management","Leadership Development","Managerial Skills Development","Corporate Strategy Creation and Implementation","Performance Management","Strategic HRM"],"biography":["Coach and Consultant","Strategic HR Management","Impactive Leadership","Creating and Implementing Corporate Strategy","Senior Management Advisor"]}', '{"badge":"Recognised Speaker Credentials","heading":"Certification\\non Successful\\nCompletion","image":"/images/solutions/strategic-hr/certificate_image.jpg","paragraphs":["When you finish the program, you will receive the Advancing Trainer Development Certification, awarded by EIU Paris and the Global Association of Training & Development (GATD).","This certification recognises your achievement in workforce development and shows your commitment to excellence in learning design, knowledge transfer, and raising human capital standards worldwide."]}', 'session_plan', '{"heading":"2 Days of Strategic L&D","badge":"2 Days","days":[{"label":"DAY 1","sessions":[{"color":"red","title":"Participant Insights","bullets":["Participant interests & challenges","First live knowledge practice","Review & discussion"]},{"color":"dark","title":"Learning Design","bullets":["Knowledge objectives and session design","Second live knowledge practice, review and feedback","Knowledge learning review – methods, approaches, personal earning"]},{"color":"red","title":"Skills Development","bullets":["Capability (skills) objectives and design (general)","Individual design and preparation – skills development","Review & discussion"]},{"color":"dark","title":"Skills Practice","bullets":["Capability (skills) practice session","Review; trainer “hat”; best practices and takeaways","Personal learning"]}]},{"label":"DAY 2","sessions":[{"color":"red","title":"Attitude Shaping","bullets":["Shaping attitude, engagement and willing commitment — the rationale","Attitude objectives in learning","Range of approaches and timeframes"]},{"color":"dark","title":"Commitment Design","bullets":["Design of a commitment-shaping session","Practice session delivery","Review, feedback & discussion"]},{"color":"red","title":"Evaluation Review","bullets":["Learning evaluation","The easy, the hard, the practical, the implementable","Review & discussion"]},{"color":"dark","title":"Trainer Closure","bullets":["Trainer development quiz","Personal learning & takeaways","Certification and thank you\'s"]}]}]}', 1, 1, 6);

INSERT INTO solution_programs (child_solution_id, slug, eyebrow, title, description, banner, card_image, subheading, subtext, rating, reviews, price_cents, currency, pricing_period, pricing_heading, pricing_description, brochure, registration_heading, overview, gains_heading, gains, focus_heading, focus_areas, faqs, facilitator, certification, layout_type, layout_data, is_published, is_active, sort_order)
VALUES ((SELECT id FROM child_solutions WHERE slug='strategic-hr' LIMIT 1), 'management-best-practices', 'Certified Programs', 'Management: Best Practices for Best Results', 'Join a 3-day executive programme to learn the management frameworks used by top global companies to boost precision, productivity, and growth.', '/images/solutions/strategic-hr/management-best-practices-for-best-results-banner.png', '/images/solutions/strategic-hr/management-best-practices-for-best-results.jpg', 'Lead with Confidence. Manage with Excellence. Deliver Results.', 'This programme transforms good managers into great ones — equipping them with proven best practices in team leadership, performance management, communication, and operational execution.', 4.9, 305, 385000, 'SGD', '/Person', 'Why It\'s Worth', 'This investment gives you a respected EIU-Paris credential and practical methods to improve how your team works. You’ll get tools to set high standards across your department, leading to steady results and better productivity.', '/brochures/management-best-practise-best-result.pdf', 'Management: Best Practices for Best Results', '{"title":"Management Best Practice Best Results","description":"Boost your operational skills with this top Management Best Practices certification. The programme helps you build practical skills in modern management to improve performance, efficiency, and quality. You will learn how to use best practices in planning, execution, performance review, team leadership, and decision-making to get better results.","image":"/images/solutions/strategic-hr/management_best_practise_overview.jpg"}', NULL, '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","text":"Apply proven management best practices to achieve better results"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","text":"Use advanced decision-making models to handle important business challenges confidently"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","text":"Make decisions based on structured thinking and business context"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","text":"Improve overall organizational performance management and team accountability"},{"id":5,"iconSrc":"/images/solutions/strategic-hr/5.svg","text":"Improve your planning, execution, and how well your operations run."},{"id":6,"iconSrc":"/images/solutions/strategic-hr/6.svg","text":"Develop an action plan using management best practices to improve leadership"}]', 'Focuses on Developing', '[{"id":1,"iconSrc":"/images/solutions/strategic-hr/1.svg","title":"Systemic Operational Excellence","description":"Learn to design strong management systems that deliver steady results across different business units"},{"id":2,"iconSrc":"/images/solutions/strategic-hr/2.svg","title":"High-Velocity Decision Architecture","description":"Master proven data-driven models to handle complex challenges quickly and accurately"},{"id":3,"iconSrc":"/images/solutions/strategic-hr/3.svg","title":"Sustainable Output Resilience","description":"Build management systems that keep performance high, even during fast growth or tough times"},{"id":4,"iconSrc":"/images/solutions/strategic-hr/4.svg","title":"Strategic Execution Frameworks","description":"Turn big-picture company goals into clear, well-defined, measurable daily actions you can easily track"}]', '[{"id":1,"question":"Is this a basic management course?","answer":"No, this is an advanced certification for experienced leaders. We focus on the structure of management and how to build systems that deliver top results again and again."},{"id":2,"question":"Who should enrol in this certification?","answer":"This programme is perfect for managers and leaders who are in charge of team performance and business results."},{"id":3,"question":"What will I learn from this programme?","answer":"You will learn practical management skills that help you make better decisions, lead teams, and improve performance."}]', '{"name":"Prof. Dr. Joel Farnworth","role":"Dean of Business and Management Studies, EIU-Paris","image":"/images/solutions/strategic-hr/Dr_Joel.png","bg":"/images/solutions/strategic-hr/program_facilitator_BG.png","expertise":["Human Resource Management","Leadership Development","Managerial Skills Development","Corporate Strategy Creation and Implementation","Performance Management","Strategic HRM"],"biography":["Coach and Consultant","Strategic HR Management","Impactive Leadership","Creating and Implementing Corporate Strategy","Senior Management Advisor"]}', '{"badge":"Recognised Speaker Credentials","heading":"Certification\\non Successful\\nCompletion","image":"/images/solutions/strategic-hr/certificate_image.jpg","paragraphs":["When you finish the programme, you will receive the Management Best Practices for Best Result Certification, awarded by EIU Paris and the Global Association of Training & Development (GATD).","This certification recognises your achievement in operational leadership and shows your commitment to excellent management, new ways of working, and raising business standards worldwide."]}', 'precision_pillars', '{"heading":"3 Days of Precision Management","badge":"3 Days","days":[{"label":"DAY 1","nodes":[{"circleTitle":"The Organisation & People Balance","color":"red","sideHeading":"Strategic Planning","bullets":["Strategy and alignment","AOPs and KPIs","Measurable deliverables"]},{"circleTitle":"Managers are important","color":"dark","sideHeading":"Leadership Insights","bullets":["The lead from Google","Key management capabilities","Level based capabilities"]},{"circleTitle":"The demands of the led","color":"red","sideHeading":"Employee Dynamics","bullets":["Stay or go","The key 5","Peripherals on the rise"]},{"circleTitle":"Employer of choice","color":"red","sideHeading":"Workplace Appeal","bullets":["Where the world wants to work","Key attractions for your business","Tracking impact and initiative results"]}]},{"label":"DAY 2","nodes":[{"circleTitle":"The Engaged Manager","color":"dark","sideHeading":"Survey Insights","bullets":["The survey","Interpreting results","Actions for improvement"]},{"circleTitle":"Strategic Context","color":"red","sideHeading":"Performance Planning","bullets":["Creation","Models and approaches","AOPs, KPIs & deliverables (managing the details!!)"]},{"circleTitle":"The Talent Challenge","color":"dark","sideHeading":"Talent Sourcing","bullets":["Best sourcing channels","Internal v external","Improvement areas and progress"]},{"circleTitle":"Learning from the Negative","color":"red","sideHeading":"Industry Lessons","bullets":["Poor practices – financial","Poor practices – car industry","The Nissan turnaround"]}]},{"label":"DAY 3","nodes":[{"circleTitle":"Learning from the Positive","color":"red","sideHeading":"Company Insights","bullets":["Virgin (Branson)","HSBC (sometimes)","Johnson & Johnson"]},{"circleTitle":"AI & Predictive Analytics Future Management Trends","color":"dark","sideHeading":"AI Perspectives","bullets":["Exploring AI Predictions","Consultants Views?","Participant Views?"]},{"circleTitle":"A Data Driven World","color":"red","sideHeading":"Knowledge Sources","bullets":["Did you know?","Glassdoor","Information Channels"]},{"circleTitle":"Final Thoughts","color":"dark","sideHeading":"Management Insights","bullets":["Business & People","The Successful Manager","Takeaways for Implementation"]}]}]}', 1, 1, 7);

